                estimator = Estimator(LinearDiscriminantAnalysis())
        else:
            raise SkipTest("Can't instantiate estimator {} which requires "
                           "parameters {}".format(Estimator.__name__,
                                                  required_parameters))
    else:
        estimator = Estimator()
    return estimator

